/**
 * Helper: is HTTP(S) request to avoid caching a non-HTTP(S) request. This is usually something injected by a browser extension (e.g., React DevTools) with a chrome-extension:// URL.
 * @param {*} reqOrUrl 
 * @returns 
 */
const isHttpRequest = (reqOrUrl) => {
  const u = reqOrUrl instanceof Request ? new URL(reqOrUrl.url) : new URL(reqOrUrl);
  return u.protocol === 'http:' || u.protocol === 'https:';
};

// Helper: fetch with cache-bust using the revision (precache-only)
async function cacheWithRevision(cache, entry) {
  const { url } = entry;
  // If you filename-hash assets (app.abc123.js), a normal request is enough.
  // If not, force a revalidation by adding a query with the revision:
  const req = new Request(url, { cache: 'reload' });
  const res = await fetch(req);
  if (!res.ok) throw new Error(`Precache failed for ${url}: ${res.status}`);
  await cache.put(url, res.clone());
}

// INSTALL: fill the precache
self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(PRECACHE_NAME);
    await Promise.all(PRECACHE_MANIFEST.map(e => cacheWithRevision(cache, e)));
    // Activate new SW immediately after install:
    await self.skipWaiting();
  })());
});

// ACTIVATE: clean old caches
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(
      keys
        .filter(k => ![PRECACHE_NAME, RUNTIME_NAME, JSON_CACHE].includes(k))
        .map(k => caches.delete(k))
    );
    await self.clients.claim();
  })());
});

// Strategy helpers
const isHTMLNavigation = (req) =>
  req.mode === 'navigate' ||
  (req.method === 'GET' && req.headers.get('accept')?.includes('text/html'));

const isImmutableAsset = (url) =>
  url.pathname.match(/\.(?:css|js|wasm|woff2?|png|jpe?g|svg)$/i);

const isJSONData = (url) =>
  url.pathname.startsWith('/public/web/') && url.pathname.endsWith('.json'); // adjust to your JSON path

// FETCH: route by type
self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);

  // 1) Navigations: Network-first with offline fallback
  if (isHTMLNavigation(req)) {
    event.respondWith((async () => {
      try {
        const network = await fetch(req);
        // Optionally, update the precache copy of index.html
        if (isHttpRequest(req)) {
          const cache = await caches.open(PRECACHE_NAME);
          // be explicit about which URL you cache; ensure it's http(s)
          await cache.put('index.html', network.clone());
        }
        return network;
      } catch {
        const cache = await caches.open(PRECACHE_NAME);
        return (await cache.match('/index.html')) ||
               (await cache.match('/offline.html')) ||
               new Response('Offline', { status: 503 });
      }
    })());
    return;
  }

  // 2) Static assets: Cache-first
  if (isImmutableAsset(url)) {
    event.respondWith((async () => {
      const cache = await caches.open(PRECACHE_NAME);
      const cached = await cache.match(req);
      if (cached) return cached;
      const res = await fetch(req);
      // only cache successful http(s) GETs
      if (res.ok && req.method === 'GET' && isHttpRequest(req)) {
        const cache = await caches.open(PRECACHE_NAME);
        await cache.put(req, res.clone());
      }
      return res;
    })());
    return;
  }

  // 3) JSON that updates sometimes: Stale-while-revalidate (+ notify)
  if (isJSONData(url)) {
    event.respondWith((async () => {
      const cache = await caches.open(JSON_CACHE);
      const cached = await cache.match(req);
      const fetchPromise = fetch(req).then(async (res) => {
        if (res.ok && isHttpRequest(req)) {
          const cache = await caches.open(JSON_CACHE);
          const old = cached ? await cached.clone().text() : null;
          const fresh = await res.clone().text();
          await cache.put(req, res.clone());
          // If changed, let clients know (so you can prompt for refresh or hot-reload panels)
          if (old !== null && old !== fresh) {
            const clientsList = await self.clients.matchAll({ type: 'window' });
            clientsList.forEach(c => c.postMessage({ type: 'json-updated', url: url.pathname }));
          }
        }
        return res;
      }).catch(() => null);

      // Serve cached immediately if present; else wait for network
      return cached || fetchPromise || new Response('Offline JSON', { status: 503 });
    })());
    return;
  }

  // 4) Everything else: try network, fall back to runtime cache, then nothing
  event.respondWith((async () => {
    const cache = await caches.open(RUNTIME_NAME);
    try {
      const res = await fetch(req);
      if (res.ok && req.method === 'GET' && isHttpRequest(req)) {
        const cache = await caches.open(RUNTIME_NAME);
        await cache.put(req, res.clone());
      }
      return res;
    } catch {
      const cache = await caches.open(RUNTIME_NAME);
      const cached = isHttpRequest(req) ? await cache.match(req) : null;
      return cached || new Response('Offline', { status: 503 });
    }
  })());
});

// Optional: listen for "SKIP_WAITING" from the page to activate immediately
self.addEventListener('message', (event) => {
  if (event.data === 'SKIP_WAITING') self.skipWaiting();
});
